async(page)=>{await page.goto('http://127.0.0.1:43235/fcs/craft/cutting/replacement-fabric-fei-tickets');await page.waitForSelector('[data-hpb-action=detail]');return await page.evaluate(async()=>{const r=await import('/src/data/fcs/cutting/replacement-fabric-repository.ts'),s=await import('/src/data/fcs/cutting/replacement-fabric-source.ts'),t=await import('/src/data/fcs/runtime-process-tasks.ts');const state=await r.loadReplacementFabricState();return {rows:s.listReplacementFabricOrderRows().map(row=>({id:row.order.productionOrderId,keys:row.scopes.map(s=>s.assignmentKey),tickets:state.tickets.filter(t=>t.productionOrderId===row.order.productionOrderId).map(t=>({id:t.id,key:t.assignmentKey,invalid:t.invalidatedAt,prints:state.prints.filter(p=>p.ticketId===t.id).length}))})),tasks:t.listRuntimeProcessTasks().filter(x=>x.productionOrderId.includes('9003')).map(x=>({id:x.taskId,business:x.processBusinessCode,code:x.processCode,factory:x.assignedFactoryId})),receipts:state.receipts}})}
